"""Name resolution and type checking for the AST subset.

Visibility rules
----------------
* A ``let`` binds from the statement *after* its declaration statement.
  (The initializer therefore cannot reference the variable itself.)
* Nested blocks push a fresh scope; an inner ``let`` shadows an outer
  binding of the same name (and is *not* a duplicate).
* A second ``let`` for the same name in the *same* scope raises
  :class:`DuplicateSymbolError`; a reference to an unbound name raises
  :class:`UndefinedSymbolError`.

Type rules
----------
* Arithmetic accepts only ``int`` operands and yields ``int``.
* Boolean ``and``/``or`` accept only ``bool`` and yield ``bool``.
* All six comparisons accept matching operand types and yield ``bool``;
  ``void`` never appears in an expression.
* Assignment, ``return`` and call arguments must match declarations.
* Calls must resolve to a known function with matching arity and argument
  types; the call type is the callee return type, so calls to ``void``
  functions are statement-less and rejectable.

This pass also computes reachability: a reachable path leaving a non-void
function without a ``return`` raises :class:`MissingReturnError`.
"""
from typing import Optional

from .errors import (
    DuplicateSymbolError,
    MissingReturnError,
    TypeCheckError,
    UndefinedSymbolError,
)

INT = "int"
BOOL = "bool"
VOID = "void"


class _Func:
    __slots__ = ("name", "param_types", "ret_type")

    def __init__(self, name: str, param_types: list[str], ret_type: str):
        self.name = name
        self.param_types = param_types
        self.ret_type = ret_type


class _Scope:
    """One block scope; ``declared`` is ordered for deterministic errors."""

    __slots__ = ("parent", "declared")

    def __init__(self, parent: Optional["_Scope"]):
        self.parent = parent
        self.declared: dict[str, str] = {}

    def declare(self, name: str, typ: str) -> None:
        if name in self.declared:
            raise DuplicateSymbolError(
                f"duplicate declaration of {name!r} in the same scope"
            )
        self.declared[name] = typ

    def lookup(self, name: str) -> Optional[str]:
        scope: Optional[_Scope] = self
        while scope is not None:
            if name in scope.declared:
                return scope.declared[name]
            scope = scope.parent
        return None


class SemanticAnalyzer:
    """Check one validated program AST."""

    def __init__(self, ast: dict):
        self.ast = ast
        # Function table is built in AST order for deterministic messages.
        self.functions: dict[str, _Func] = {}
        self._build_function_table()

    def _build_function_table(self) -> None:
        for func in self.ast["functions"]:
            name = func["name"]
            if name in self.functions:
                raise DuplicateSymbolError(
                    f"duplicate function declaration {name!r}"
                )
            self.functions[name] = _Func(
                name, [p["type"] for p in func["params"]], func["ret_type"]
            )

    def check(self) -> None:
        for func in self.ast["functions"]:
            self._check_function(func)

    # -- functions ---------------------------------------------------------

    def _check_function(self, func: dict) -> None:
        scope = _Scope(None)
        for param in func["params"]:
            # Parameter names occupy the top-level function scope; duplicates
            # here (e.g. two params of the same name) are also duplicates.
            scope.declare(param["name"], param["type"])
        self._ret_type = func["ret_type"]
        self._func_name = func["name"]
        completed = self._check_stmts(func["body"], scope)
        if self._ret_type != VOID and not completed:
            raise MissingReturnError(
                f"function {func['name']!r}: missing return on a reachable path"
            )

    # -- statements --------------------------------------------------------

    def _check_stmts(self, stmts: list, scope: _Scope) -> bool:
        """Return True if every path through these statements returns."""
        current = scope
        for stmt in stmts:
            if self._check_stmt(stmt, current):
                return True
        return False

    def _check_stmt(self, stmt: dict, scope: _Scope) -> bool:
        """Return True if control cannot reach the statement after this one."""
        kind = stmt["kind"]
        if kind == "let":
            typ = stmt["type"]
            # The initializer is checked *before* the name is bound: a let
            # is visible starting with the following statement.
            init_type = self._type_of(stmt["init"], scope)
            if init_type != typ:
                raise TypeCheckError(
                    f"let {stmt['name']!r}: declared {typ}, initializer is {init_type}"
                )
            scope.declare(stmt["name"], typ)
            return False
        if kind == "assign":
            name = stmt["target"]
            got = self._type_of(stmt["value"], scope)
            want = scope.lookup(name)
            if want is None:
                raise UndefinedSymbolError(
                    f"assignment to undeclared variable {name!r}"
                )
            if got != want:
                raise TypeCheckError(
                    f"assign to {name!r}: declared {want}, value is {got}"
                )
            return False
        if kind == "if":
            cond_t = self._type_of(stmt["cond"], scope)
            if cond_t != BOOL:
                raise TypeCheckError(f"if condition must be bool, got {cond_t}")
            then_done = self._check_stmts(stmt["then"], _Scope(scope))
            else_done = self._check_stmts(stmt["else"], _Scope(scope))
            return then_done and else_done
        if kind == "while":
            cond_t = self._type_of(stmt["cond"], scope)
            if cond_t != BOOL:
                raise TypeCheckError(f"while condition must be bool, got {cond_t}")
            # The loop may run zero times, so fallthrough always survives;
            # a return inside the body does not make the loop completing.
            self._check_stmts(stmt["body"], _Scope(scope))
            return False
        if kind == "return":
            value = stmt["value"]
            if self._ret_type == VOID:
                if value is not None:
                    got = self._type_of(value, scope)
                    raise TypeCheckError(
                        f"void function {self._func_name!r} returned {got}"
                    )
            else:
                if value is None:
                    raise TypeCheckError(
                        f"function {self._func_name!r} must return {self._ret_type}"
                    )
                got = self._type_of(value, scope)
                if got != self._ret_type:
                    raise TypeCheckError(
                        f"return in {self._func_name!r}: declared {self._ret_type}, got {got}"
                    )
            return True
        # block
        return self._check_stmts(stmt["body"], _Scope(scope))

    # -- expressions -------------------------------------------------------

    def _type_of(self, expr: dict, scope: _Scope) -> str:
        kind = expr["kind"]
        if kind == "int":
            return INT
        if kind == "bool":
            return BOOL
        if kind == "var":
            name = expr["name"]
            typ = scope.lookup(name)
            if typ is None:
                raise UndefinedSymbolError(f"reference to undeclared variable {name!r}")
            return typ
        if kind == "arith":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != INT or rt != INT:
                raise TypeCheckError(
                    f"arithmetic '{expr['op']}' requires int operands, got {lt} and {rt}"
                )
            return INT
        if kind == "compare":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != rt:
                raise TypeCheckError(
                    f"comparison '{expr['op']}' requires matching types, got {lt} and {rt}"
            )
            return BOOL
        if kind == "logical":
            lt = self._type_of(expr["left"], scope)
            rt = self._type_of(expr["right"], scope)
            if lt != BOOL or rt != BOOL:
                raise TypeCheckError(
                    f"boolean '{expr['op']}' requires bool operands, got {lt} and {rt}"
                )
            return BOOL
        # call
        name = expr["name"]
        func = self.functions.get(name)
        if func is None:
            raise UndefinedSymbolError(f"call to undeclared function {name!r}")
        args = expr["args"]
        if len(args) != len(func.param_types):
            raise TypeCheckError(
                f"call to {name!r}: expected {len(func.param_types)} "
                f"argument(s), got {len(args)}"
            )
        for i, (arg, want) in enumerate(zip(args, func.param_types)):
            got = self._type_of(arg, scope)
            if got != want:
                raise TypeCheckError(
                    f"call to {name!r} argument {i + 1}: expected {want}, got {got}"
                )
        if func.ret_type == VOID:
            raise TypeCheckError(
                f"call to void function {name!r} cannot be used as a value"
            )
        return func.ret_type


def analyze(ast: dict) -> None:
    """Run name resolution and type checking over a validated AST."""
    SemanticAnalyzer(ast).check()

"""Dead-code elimination on pruned SSA form.

The entry point :func:`eliminate_dead_code` takes an SSA :class:`Module`
produced by :func:`~compiler_ir.ssa.to_ssa` and returns a brand new SSA
:class:`Module` with unreachable definitions removed; the input module is
never mutated and shares no mutable function, block, instruction or phi
container with the result.

Liveness is traced per function, definition-to-use, from fixed roots:

* every operand of a ``Return`` or ``Branch`` terminator;
* every ``Call`` instruction, regardless of whether its result is used --
  the call itself and its position in the instruction stream are observable
  behavior -- together with all of its argument definitions.

A ``Const``, ``BinOp`` or ``Phi`` that cannot reach one of those roots is
deleted.  The trace runs on the whole function at once, so chains feeding
only other dead definitions and closed phi cycles die together in one pass;
elimination is then repeated until no new dead definition appears.

The pass is purely subtractive.  No constants are folded, branches
rewritten, blocks deleted or control flow reordered.  Function order,
signatures, parameters, return types, block labels and order, terminators,
the relative order of surviving instructions and the predecessor order of
surviving phis are all preserved, and SSA numbers of surviving values are
left untouched (the output may therefore contain numbering holes).

Applying the pass to an already minimal module returns an independent,
structurally and textually equivalent copy, so a second
:func:`eliminate_dead_code` changes nothing.  A non-:class:`Module` object
raises :class:`TypeError`; a non-SSA :class:`Module` raises
:class:`ValueError`.
"""
from .ir_nodes import (
    BinOp,
    Block,
    Branch,
    Call,
    Const,
    Copy,
    Function,
    Jump,
    Module,
    Parameter,
    Phi,
    Return,
    Temp,
)


def eliminate_dead_code(module: Module) -> Module:
    """Return a new SSA :class:`Module` with dead definitions removed.

    The input module is left untouched; the result shares no mutable
    function, block, instruction or phi object with it.

    :raises TypeError: if ``module`` is not a :class:`Module` instance.
    :raises ValueError: if ``module`` is not in SSA form.
    """
    if not isinstance(module, Module):
        raise TypeError(
            "eliminate_dead_code expects a Module, got "
            f"{type(module).__name__}"
        )
    if not getattr(module, "ssa", False):
        raise ValueError("eliminate_dead_code expects an SSA Module")
    return Module(
        [_eliminate_in_function(func) for func in module.functions], ssa=True
    )


# --------------------------------------------------------------------------
# Operand helpers (mirror the ones used by the SSA conversion)
# --------------------------------------------------------------------------


def _operands(ins):
    if isinstance(ins, BinOp):
        return [ins.left, ins.right]
    if isinstance(ins, Call):
        return list(ins.args)
    # Const has no operands; a Copy cannot survive the non-SSA -> SSA
    # conversion (it folds into renaming) but is treated as pure anyway.
    if isinstance(ins, Copy):
        return [ins.src]
    return []


def _term_operands(term):
    if isinstance(term, Return) and term.value is not None:
        return [term.value]
    if isinstance(term, Branch):
        return [term.cond]
    return []


# --------------------------------------------------------------------------
# Per-function elimination
# --------------------------------------------------------------------------


def _live_definitions(func: Function) -> set:
    """Return the ids of values live from the terminator/call roots.

    Roots are every value read by a ``Return`` or ``Branch`` and *every*
    ``Call`` instruction (plus, transitively, its arguments): a call whose
    result is unused is still observable.  From each root the use-def graph
    -- instruction operands and phi incoming values -- is walked to a
    fixpoint, so a value only reachable from dead code or a closed phi
    cycle is absent from the result.
    """
    phi_by_dest: dict = {}
    operands_by_dest: dict = {}
    worklist: list = []

    for block in func.blocks:
        for ins in block.instructions:
            operands_by_dest[id(ins.dest)] = _operands(ins)
            if isinstance(ins, Call):
                # The call itself is a root even if its result is unused:
                # reaching its dest below also pulls in its arguments.
                worklist.append(ins.dest)
        worklist.extend(_term_operands(block.terminator))
        for phi in block.phis:
            phi_by_dest[id(phi.dest)] = phi

    live: set = set()
    while worklist:
        value = worklist.pop()
        if value is None or id(value) in live:
            continue
        live.add(id(value))
        phi = phi_by_dest.get(id(value))
        if phi is not None:
            worklist.extend(phi.entries.values())
        else:
            worklist.extend(operands_by_dest.get(id(value), ()))
    return live


def _eliminate_in_function(func: Function) -> Function:
    live = _live_definitions(func)

    new_blocks = [Block(block.id) for block in func.blocks]
    block_map = dict(zip(func.blocks, new_blocks))

    # Pre-create one fresh Temp for every surviving definition before
    # cloning anything: a phi in an earlier block (e.g. a loop header's
    # backedge entry) can reference an instruction defined in a later
    # block, and every retained use must resolve to the very same output
    # object.  Original ids are kept, so numbering holes from removed
    # definitions remain.
    value_map: dict = {
        id(param.temp): Temp(param.temp.id, param.temp.type)
        for param in func.params
    }
    for block in func.blocks:
        for phi in block.phis:
            if id(phi.dest) in live:
                value_map[id(phi.dest)] = Temp(phi.dest.id, phi.dest.type)
        for ins in block.instructions:
            if isinstance(ins, Call) or id(ins.dest) in live:
                value_map[id(ins.dest)] = Temp(
                    ins.dest.id, ins.dest.type
                )

    def map_value(value):
        if value is None:
            return None
        mapped = value_map.get(id(value))
        if mapped is None:
            # Defensive: a referenced value with no surviving definition.
            # Never occurs for SSA IR produced by to_ssa, where every
            # operand of a live construct is itself live.
            mapped = Temp(value.id, value.type)
            value_map[id(value)] = mapped
        return mapped

    for block, new_block in zip(func.blocks, new_blocks):
        for phi in block.phis:
            if id(phi.dest) not in live:
                continue
            entries = {
                block_map[pred]: map_value(value)
                for pred, value in sorted(
                    phi.entries.items(), key=lambda item: item[0].id
                )
            }
            new_block.phis.append(Phi(map_value(phi.dest), entries))

        for ins in block.instructions:
            if not isinstance(ins, Call) and id(ins.dest) not in live:
                continue
            dest = map_value(ins.dest)
            if isinstance(ins, Const):
                clone = Const(dest, ins.value)
            elif isinstance(ins, Copy):
                clone = Copy(dest, map_value(ins.src))
            elif isinstance(ins, BinOp):
                clone = BinOp(
                    dest, ins.operator, map_value(ins.left),
                    map_value(ins.right), ins.kind, ins.type,
                )
            else:
                clone = Call(
                    dest, ins.name,
                    [map_value(arg) for arg in ins.args], ins.type,
                )
            new_block.instructions.append(clone)

        term = block.terminator
        if isinstance(term, Return):
            new_block.terminator = Return(map_value(term.value))
        elif isinstance(term, Jump):
            new_block.terminator = Jump(block_map[term.target])
        elif isinstance(term, Branch):
            new_block.terminator = Branch(
                map_value(term.cond),
                block_map[term.true_target],
                block_map[term.false_target],
            )

    new_params = [
        Parameter(
            param.name,
            param.slot,
            map_value(param.temp),
        )
        for param in func.params
    ]

    return Function(
        func.name,
        new_params,
        func.ret_type,
        list(func.locals),
        new_blocks,
        block_map[func.entry],
        ssa=True,
    )

"""The control-flow IR object model.

The IR is intentionally tiny and directly traversable::

    Module
      Function            (signature, local slots, basic blocks)
        Block             (phi nodes, ordered instructions, one terminator)
          Phi             (SSA only; one incoming value per predecessor)
          Instruction     (Const / Copy / BinOp / Call, all write a dest)
          Terminator      (Return / Jump / Branch)

Two flavors of module exist:

* non-SSA (produced by :func:`lower_module`): value references are
  :class:`Temp` -- numbered temporaries produced by instructions -- and
  :class:`Slot`, numbered mutable local storage (parameters and ``let``
  variables).  Temporaries are mostly single assignment; the sole exception
  is the result temporary of a short-circuit boolean operation, which is
  written once on each participating path, as is natural in non-SSA form.
* SSA (produced by :func:`to_ssa`): every parameter and every instruction
  result is a unique definition, slots never appear, and control-flow joins
  carry :class:`Phi` nodes listed before the block's ordinary instructions.

Both flavors reuse the same node classes; a module's ``ssa`` flag (and each
function's) says which one it is.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional, Union


@dataclass(frozen=True)
class Temp:
    id: int
    type: str

    def __str__(self) -> str:
        return f"%t{self.id}"


@dataclass(frozen=True)
class Slot:
    """A mutable local slot (parameter or ``let`` variable)."""

    id: int
    type: str

    def __str__(self) -> str:
        return f"%v{self.id}"


ValueRef = Union[Temp, Slot]


@dataclass
class Const:
    dest: Temp
    value: Union[int, bool]

    @property
    def op(self) -> str:
        return "const"


@dataclass
class Copy:
    dest: Union[Temp, Slot]
    src: ValueRef

    @property
    def op(self) -> str:
        return "copy"


@dataclass
class BinOp:
    dest: Temp
    operator: str
    left: ValueRef
    right: ValueRef
    kind: str  # "arith" or "compare"
    type: str  # result type

    @property
    def op(self) -> str:
        return self.kind


@dataclass
class Call:
    dest: Temp
    name: str
    args: list[ValueRef]
    type: str

    @property
    def op(self) -> str:
        return "call"


Instruction = Union[Const, Copy, BinOp, Call]


@dataclass(eq=False)
class Phi:
    """An SSA phi function: merges definitions from predecessor blocks.

    ``entries`` maps a predecessor :class:`Block` to the value that is live
    on that edge.  Entries are kept sorted by predecessor label whenever a
    module is emitted by :func:`to_ssa`; only reachable predecessors occur.
    """

    dest: Temp
    entries: dict["Block", ValueRef] = field(default_factory=dict)

    @property
    def op(self) -> str:
        return "phi"

    @property
    def type(self) -> str:
        return self.dest.type


@dataclass
class Return:
    value: Optional[ValueRef]

    @property
    def op(self) -> str:
        return "return"


@dataclass
class Jump:
    target: "Block"

    @property
    def op(self) -> str:
        return "jump"


@dataclass
class Branch:
    cond: ValueRef
    true_target: "Block"
    false_target: "Block"

    @property
    def op(self) -> str:
        return "br"


Terminator = Union[Return, Jump, Branch]


@dataclass(eq=False)
class Block:
    id: int
    instructions: list[Instruction] = field(default_factory=list)
    terminator: Optional[Terminator] = None
    # SSA only; empty in non-SSA blocks.  Phi nodes precede the ordinary
    # instructions.
    phis: list[Phi] = field(default_factory=list)

    @property
    def label(self) -> str:
        return f"b{self.id}"

    @property
    def is_terminated(self) -> bool:
        return self.terminator is not None


@dataclass
class Parameter:
    name: str
    slot: Slot
    # SSA only: the unique parameter definition.  None in non-SSA functions,
    # where the parameter is read through ``slot``.
    temp: Optional[Temp] = None


@dataclass
class Function:
    name: str
    params: list[Parameter]
    ret_type: str
    locals: list[Slot]
    blocks: list[Block]
    entry: Block
    ssa: bool = False

    def is_void(self) -> bool:
        return self.ret_type == "void"


@dataclass
class Module:
    functions: list[Function]
    ssa: bool = False

"""Tests for AST validation, semantic analysis, lowering and text IR."""
import unittest

from compiler_ir import (
    DuplicateSymbolError,
    InvalidAstError,
    MissingReturnError,
    TypeCheckError,
    UndefinedSymbolError,
    emit_ir,
    lower_module,
    render_module,
)


def int_(value):
    return {"kind": "int", "value": value}


def bool_(value):
    return {"kind": "bool", "value": value}


def var(name):
    return {"kind": "var", "name": name}


def arith(op, left, right):
    return {"kind": "arith", "op": op, "left": left, "right": right}


def compare(op, left, right):
    return {"kind": "compare", "op": op, "left": left, "right": right}


def logical(op, left, right):
    return {"kind": "logical", "op": op, "left": left, "right": right}


def call(name, args):
    return {"kind": "call", "name": name, "args": args}


def let(name, typ, init):
    return {"kind": "let", "name": name, "type": typ, "init": init}


def assign(target, value):
    return {"kind": "assign", "target": target, "value": value}


def if_(cond, then, else_=None):
    return {"kind": "if", "cond": cond, "then": then, "else": else_ or []}


def while_(cond, body):
    return {"kind": "while", "cond": cond, "body": body}


def ret(value=None):
    return {"kind": "return", "value": value}


def block(body):
    return {"kind": "block", "body": body}


def func(name, params, ret_type, body):
    return {"name": name, "params": params, "ret_type": ret_type, "body": body}


def param(name, typ):
    return {"name": name, "type": typ}


def program(*funcs):
    return {"functions": list(funcs)}


# Two mutually recursive-ish int functions used across tests.
COUNTER = func(
    "counter",
    [param("n", "int")],
    "int",
    [
        let("acc", "int", int_(0)),
        while_(
            compare("gt", var("n"), int_(0)),
            [
                assign("acc", arith("add", var("acc"), var("n"))),
                assign("n", arith("sub", var("n"), int_(1))),
            ],
        ),
        ret(var("acc")),
    ],
)


class LoweringTests(unittest.TestCase):
    def test_empty_void_function(self):
        text = emit_ir(program(func("noop", [], "void", [])))
        self.assertIn("function noop() -> void", text)
        self.assertIn("b0:", text)
        # The entry block's terminator is an explicit bare return.
        body = text[text.index("b0:"):]
        self.assertIn("    return\n", body)

    def test_nonvoid_with_constant_return(self):
        text = emit_ir(program(func("answer", [], "int", [ret(int_(42))])))
        self.assertIn("const 42", text)
        self.assertIn("return %t0", text)

    def test_parameters_occupy_first_slots(self):
        module = lower_module(
            program(func("add", [param("a", "int"), param("b", "int")], "int",
                        [ret(arith("add", var("a"), var("b")))]))
        )
        fn = module.functions[0]
        self.assertEqual([p.slot.id for p in fn.params], [0, 1])
        self.assertEqual(fn.locals, [])

    def test_function_call_arguments_and_result(self):
        text = emit_ir(
            program(
                func("id", [param("x", "bool")], "bool", [ret(var("x"))]),
                func("use", [], "bool", [ret(call("id", [bool_(True)]))]),
            )
        )
        self.assertIn("call id(", text)

    def test_forward_function_call_resolves(self):
        # callee is declared after the caller; the function table is global.
        text = emit_ir(
            program(
                func("use", [], "int", [ret(call("later", [int_(5)]))]),
                func("later", [param("x", "int")], "int", [ret(var("x"))]),
            )
        )
        self.assertIn("call later(%t0)", text)

    def test_short_circuit_and_branches(self):
        # and: right operand evaluated only on the true path.
        text = emit_ir(
            program(
                func(
                    "f", [], "bool",
                    [
                        let(
                            "r", "bool",
                            logical("and", bool_(True),
                                    compare("eq", int_(1), int_(1))),
                        ),
                        ret(var("r")),
                    ],
                )
            )
        )
        # The compare must live in the branch reached when left is true.
        lines = text.splitlines()
        br_line = next(i for i, l in enumerate(lines) if l.strip().startswith("br %t0"))
        compare_line = next(i for i, l in enumerate(lines) if "compare eq" in l)
        self.assertGreater(compare_line, br_line)
        # The false (short-circuit) path must contain const false, no compare.
        self.assertIn("const false", text)

